window.BOOK={"key":"madaih","app":"mutoon-madaih","lsk":"mutoon_madaih_v1","prefix":"ma_","title":"المدائح النبوية","sub":"مختارات · من أبي طالب وحسان إلى البوصيري وشوقي · ٢١٥ بيتًا","poems":[{"id":"madaih","title":"المدائح النبوية","nazim":"مختارات من عدة شعراء","death":"","meter":"الطويل والبسيط والكامل والخفيف والوافر","source":"سيرة ابن هشام وصحيح البخاري ودواوين الشعراء (موقع الديوان)، مع العمدة في إعراب البردة وطبعة هنداوي للشوقيات","srcUrl":"https://www.aldiwan.net/","note":"أشهر وأقوى أبيات المديح النبوي من كل قصيدة: أبو طالب، حسان بن ثابت، عبد الله بن رواحة، العباس، كعب بن زهير، الأعشى، ثم البوصيري (البردة والهمزية)، والبارودي، وشوقي (نهج البردة، ولد الهدى، سلوا قلبي). قوبلت كل مقطوعة كلمةً كلمةً بسكربت بمصدر ثانٍ وفُحص وزن كل شطر. تُركت الأبيات التي فيها استغاثة أو توسل أو غلو. شكل همزية البوصيري أُكمل يدويًّا، وقصة وفادة الأعشى وحديث أبيات العباس لا يثبتان إسنادًا، والتفصيل في تقريري المصادر (madaih-a و madaih-b).","verses":[["كَذَبْتُمْ وَبَيْتِ اللَّهِ نُبْزَى مُحَمَّدًا","وَلَمَّا نُطَاعِنْ دُونَهُ وَنُنَاضِلِ"],["وَنُسْلِمُهُ حَتَّى نُصَرَّعَ حَوْلَهُ","وَنَذْهَلَ عَنْ أَبْنَائِنَا وَالْحَلَائِلِ"],["وَمَا تَرْكُ قَوْمٍ لَا أَبَا لَكَ سَيِّدًا","يَحُوطُ الذِّمَارَ غَيْرَ ذَرْبٍ مُوَاكِلِ"],["وَأَبْيَضَ يُسْتَسْقَى الْغَمَامُ بِوَجْهِهِ","ثِمَالُ الْيَتَامَى عِصْمَةٌ لِلْأَرَامِلِ"],["يَلُوذُ بِهِ الْهُلَّاكُ مِنْ آلِ هَاشِمٍ","فَهُمْ عِنْدَهُ فِي رَحْمَةٍ وَفَوَاضِلِ"],["لَعَمْرِي لَقَدْ كُلِّفْتُ وَجْدًا بِأَحْمَدٍ","وَإِخْوَتِهِ دَأْبَ الْمُحِبِّ الْمُوَاصِلِ"],["فَلَا زَالَ فِي الدُّنْيَا جَمَالًا لِأَهْلِهَا","وَزَيْنًا لِمَنْ وَالَاهُ رَبُّ الْمَشَاكِلِ"],["فَمَنْ مِثْلُهُ فِي النَّاسِ أَيُّ مُؤَمَّلٍ","إِذَا قَاسَهُ الْحُكَّامُ عِنْدَ التَّفَاضُلِ"],["حَلِيمٌ رَشِيدٌ عَادِلٌ غَيْرُ طَائِشٍ","يُوَالِي إِلَهًا لَيْسَ عَنْهُ بِغَافِلِ"],["فَوَاللَّهِ لَوْلَا أَنْ أَجِيءَ بِسُبَّةٍ","تُجَرُّ عَلَى أَشْيَاخِنَا فِي الْمَحَافِلِ"],["لَكُنَّا اتَّبَعْنَاهُ عَلَى كُلِّ حَالَةٍ","مِنَ الدَّهْرِ جِدًّا غَيْرَ قَوْلِ التَّهَازُلِ"],["لَقَدْ عَلِمُوا أَنَّ ابْنَنَا لَا مُكَذَّبٌ","لَدَيْنَا وَلَا يُعْنَى بِقَوْلِ الْأَبَاطِلِ"],["فَأَصْبَحَ فِينَا أَحْمَدٌ فِي أَرُومَةٍ","تُقَصِّرُ عَنْهُ سُورَةُ الْمُتَطَاوِلِ"],["حَدِبْتُ بِنَفْسِي دُونَهُ وَحَمَيْتُهُ","وَدَافَعْتُ عَنْهُ بِالذُّرَى وَالْكَلَاكِلِ"],["فَأَيَّدَهُ رَبُّ الْعِبَادِ بِنَصْرِهِ","وَأَظْهَرَ دِينًا حَقُّهُ غَيْرُ بَاطِلِ"],["أَغَرُّ عَلَيْهِ لِلنُّبُوَّةِ خَاتَمٌ","مِنَ اللَّهِ مَشْهُودٌ يَلُوحُ وَيَشْهَدُ"],["وَضَمَّ الْإِلَهُ اسْمَ النَّبِيِّ إِلَى اسْمِهِ","إِذَا قَالَ فِي الْخَمْسِ الْمُؤَذِّنُ أَشْهَدُ"],["وَشَقَّ لَهُ مِنِ اسْمِهِ لِيُجِلَّهُ","فَذُو الْعَرْشِ مَحْمُودٌ وَهَذَا مُحَمَّدُ"],["نَبِيٌّ أَتَانَا بَعْدَ يَأْسٍ وَفَتْرَةٍ","مِنَ الرُّسْلِ وَالْأَوْثَانُ فِي الْأَرْضِ تُعْبَدُ"],["فَأَمْسَى سِرَاجًا مُسْتَنِيرًا وَهَادِيًا","يَلُوحُ كَمَا لَاحَ الصَّقِيلُ الْمُهَنَّدُ"],["وَأَنْذَرَنَا نَارًا وَبَشَّرَ جَنَّةً","وَعَلَّمَنَا الْإِسْلَامَ فَاللَّهَ نَحْمَدُ"],["وَأَحْسَنُ مِنْكَ لَمْ تَرَ قَطُّ عَيْنِي","وَأَجْمَلُ مِنْكَ لَمْ تَلِدِ النِّسَاءُ"],["خُلِقْتَ مُبَرَّأً مِنْ كُلِّ عَيْبٍ","كَأَنَّكَ قَدْ خُلِقْتَ كَمَا تَشَاءُ"],["وَقَالَ اللَّهُ قَدْ أَرْسَلْتُ عَبْدًا","يَقُولُ الْحَقَّ إِنْ نَفَعَ الْبَلَاءُ"],["شَهِدْتُ بِهِ فَقُومُوا صَدِّقُوهُ","فَقُلْتُمْ لَا نَقُومُ وَلَا نَشَاءُ"],["وَجِبْرِيلٌ أَمِينُ اللَّهِ فِينَا","وَرُوحُ الْقُدْسِ لَيْسَ لَهُ كِفَاءُ"],["أَلَا أَبْلِغْ أَبَا سُفْيَانَ عَنِّي","فَأَنْتَ مُجَوَّفٌ نَخِبٌ هَوَاءُ"],["هَجَوْتَ مُحَمَّدًا فَأَجَبْتُ عَنْهُ","وَعِنْدَ اللَّهِ فِي ذَاكَ الْجَزَاءُ"],["أَتَهْجُوهُ وَلَسْتَ لَهُ بِكُفْءٍ","فَشَرُّكُمَا لِخَيْرِكُمَا الْفِدَاءُ"],["هَجَوْتَ مُبَارَكًا بَرًّا حَنِيفًا","أَمِينَ اللَّهِ شِيمَتُهُ الْوَفَاءُ"],["فَمَنْ يَهْجُو رَسُولَ اللَّهِ مِنْكُمْ","وَيَمْدَحُهُ وَيَنْصُرُهُ سَوَاءُ"],["فَإِنَّ أَبِي وَوَالِدَهُ وَعِرْضِي","لِعِرْضِ مُحَمَّدٍ مِنْكُمْ وِقَاءُ"],["لِسَانِي صَارِمٌ لَا عَيْبَ فِيهِ","وَبَحْرِي لَا تُكَدِّرُهُ الدِّلَاءُ"],["بِطَيْبَةَ رَسْمٌ لِلرَّسُولِ وَمَعْهَدُ","مُنِيرٌ وَقَدْ تَعْفُو الرُّسُومُ وَتَهْمُدُ"],["وَلَا تَمْتَحِي الْآيَاتُ مِنْ دَارِ حُرْمَةٍ","بِهَا مِنْبَرُ الْهَادِي الَّذِي كَانَ يَصْعَدُ"],["وَوَاضِحُ آثَارٍ وَبَاقِي مَعَالِمٍ","وَرَبْعٌ لَهُ فِيهِ مُصَلًّى وَمَسْجِدُ"],["بِهَا حُجُرَاتٌ كَانَ يَنْزِلُ وَسْطَهَا","مِنَ اللَّهِ نُورٌ يُسْتَضَاءُ وَيُوقَدُ"],["مَعَارِفُ لَمْ تُطْمَسْ عَلَى الْعَهْدِ آيُهَا","أَتَاهَا الْبِلَى فَالْآيُ مِنْهَا تَجَدَّدُ"],["عَرَفْتُ بِهَا رَسْمَ الرَّسُولِ وَعَهْدَهُ","وَقَبْرًا بِهَا وَارَاهُ فِي التُّرْبِ مُلْحِدُ"],["وَهَلْ عَدَلَتْ يَوْمًا رَزِيَّةُ هَالِكٍ","رَزِيَّةَ يَوْمٍ مَاتَ فِيهِ مُحَمَّدُ"],["تَقَطَّعَ فِيهِ مَنْزِلُ الْوَحْيِ عَنْهُمُ","وَقَدْ كَانَ ذَا نُورٍ يَغُورُ وَيُنْجِدُ"],["يَدُلُّ عَلَى الرَّحْمَنِ مَنْ يَقْتَدِي بِهِ","وَيُنْقِذُ مِنْ هَوْلِ الْخَزَايَا وَيُرْشِدُ"],["إِمَامٌ لَهُمْ يَهْدِيهِمُ الْحَقَّ جَاهِدًا","مُعَلِّمُ صِدْقٍ إِنْ يُطِيعُوهُ يُسْعَدُوا"],["عَفُوٌّ عَنِ الزَّلَّاتِ يَقْبَلُ عُذْرَهُمْ","وَإِنْ يُحْسِنُوا فَاللَّهُ بِالْخَيْرِ أَجْوَدُ"],["عَزِيزٌ عَلَيْهِ أَنْ يَجُورُوا عَنِ الْهُدَى","حَرِيصٌ عَلَى أَنْ يَسْتَقِيمُوا وَيَهْتَدُوا"],["وَمَا فَقَدَ الْمَاضُونَ مِثْلَ مُحَمَّدٍ","وَلَا مِثْلُهُ حَتَّى الْقِيَامَةِ يُفْقَدُ"],["وَفِينَا رَسُولُ اللَّهِ يَتْلُو كِتَابَهُ","إِذَا انْشَقَّ مَعْرُوفٌ مِنَ الْفَجْرِ سَاطِعُ"],["أَرَانَا الْهُدَى بَعْدَ الْعَمَى فَقُلُوبُنَا","بِهِ مُوقِنَاتٌ أَنَّ مَا قَالَ وَاقِعُ"],["يَبِيتُ يُجَافِي جَنْبَهُ عَنْ فِرَاشِهِ","إِذَا اسْتَثْقَلَتْ بِالْمُشْرِكِينَ الْمَضَاجِعُ"],["مِنْ قَبْلِهَا طِبْتَ فِي الظِّلَالِ وَفِي","مُسْتَوْدَعٍ حَيْثُ يُخْصَفُ الْوَرَقُ"],["ثُمَّ هَبَطْتَ الْبِلَادَ لَا بَشَرٌ","أَنْتَ وَلَا مُضْغَةٌ وَلَا عَلَقُ"],["بَلْ نُطْفَةٌ تَرْكَبُ السَّفِينَ وَقَدْ","أَلْجَمَ نَسْرًا وَأَهْلَهُ الْغَرَقُ"],["تُنْقَلُ مِنْ صَالِبٍ إِلَى رَحِمٍ","إِذَا مَضَى عَالَمٌ بَدَا طَبَقُ"],["حَتَّى احْتَوَى بَيْتُكَ الْمُهَيْمِنُ مِنْ","خِنْدِفَ عَلْيَاءَ تَحْتَهَا النُّطُقُ"],["وَأَنْتَ لَمَّا وُلِدْتَ أَشْرَقَتِ الْـ","ـأَرْضُ وَضَاءَتْ بِنُورِكَ الْأُفُقُ"],["فَنَحْنُ فِي ذَلِكَ الضِّيَاءِ وَفِي النُّـ","ـورِ وَسُبْلِ الرَّشَادِ نَخْتَرِقُ"],["أُنْبِئْتُ أَنَّ رَسُولَ اللَّهِ أَوْعَدَنِي","والعَفْوُ عِنْدَ رَسُولِ اللَّهِ مَأْمُولُ"],["مَهْلًا هَدَاكَ الذِي أَعْطَاكَ نَافِلَةَ","الْقُرْآنِ فِيهَا مَوَاعِيظٌ وَتَفْصِيلُ"],["لَا تَأْخُذَنِّي بِأَقْوَالِ الْوُشَاةِ وَلَمْ","أُذْنِبْ وإنْ كَثُرَتْ فِيَّ الْأَقَاوِيلُ"],["لَقَدْ أَقُومُ مَقَامًا لَوْ يَقُومُ بِهِ","أَرَى وَأَسْمَعُ مَا لَوْ يَسْمَعُ الْفِيلُ"],["لَظَلَّ يُرْعَدُ إِلَّا أَنْ يَكُونَ لَهُ","مِنَ الرَّسُولِ بِإِذْنِ اللَّهِ تَنْوِيلُ"],["حَتَّى وَضَعْتُ يَمِينِي لَا أُنَازِعُهُ","فِي كَفِّ ذِي نَقِمَاتٍ قِيلُهُ الْقِيلُ"],["إِنَّ الرَّسُولَ لَسَيْفٌ يُسْتَضَاءُ بِهِ","مُهَنَّدٌ مِنْ سُيُوفِ اللَّهِ مَسْلُولُ"],["فِي عُصْبةٍ مِنْ قُرَيْشٍ قَالَ قَائِلُهُمْ","بِبَطْنِ مَكَّةَ لَمَّا أَسْلَمُوا زُولُوا"],["زَالُوا فمَا زَالَ أَنْكَاسٌ وَلَا كُشُفٌ","عِنْدَ اللِّقَاءِ وَلَا مِيلٌ مَعَازِيلُ"],["شُمُّ الْعَرانينِ أَبْطَالٌ لَبُوسُهُمُ","مِنْ نَسْجِ دَاوُدَ فِي الْهَيْجَا سَرَابِيلُ"],["وَآلَيْتُ لَا آوِي لَهَا مِنْ كَلَالَةٍ","وَلَا مِنْ حَفًى حَتَّى تُلَاقِي مُحَمَّدَا"],["مَتَى مَا تُنَاخِي عِنْدَ بَابِ ابْنِ هَاشِمٍ","تُرَاحِي وَتَلْقَيْ مِنْ فَوَاضِلِهِ نَدَى"],["نَبِيًّا يَرَى مَا لَا تَرَوْنَ وَذِكْرُهُ","أَغَارَ لَعَمْرِي فِي الْبِلَادِ وَأَنْجَدَا"],["لَهُ صَدَقَاتٌ مَا تُغِبُّ وَنَائِلٌ","وَلَيْسَ عَطَاءُ الْيَوْمِ مَانِعَهُ غَدَا"],["أَجِدَّكَ لَمْ تَسْمَعْ وَصَاةَ مُحَمَّدٍ","نَبِيِّ الْإِلَهِ حَيْثُ أَوْصَى وَأَشْهَدَا"],["إِذَا أَنْتَ لَمْ تَرْحَلْ بِزَادٍ مِنَ التُّقَى","وَلَاقَيْتَ بَعْدَ الْمَوْتِ مَنْ قَدْ تَزَوَّدَا"],["نَدِمْتَ عَلَى أَنْ لَا تَكُونَ كَمِثْلِهِ","فَتُرْصِدَ لِلْأَمْرِ الَّذِي كَانَ أَرْصَدَا"],["أَمِنْ تَذَكُّرِ جِيرَانٍ بِذِي سَلَمِ","مَزَجْتَ دَمْعًا جَرَى مِنْ مُقْلَةٍ بِدَمِ"],["أَمْ هَبَّتِ الرِّيحُ مِنْ تِلْقَاءِ كَاظِمَةٍ","وَأَوْمَضَ الْبَرْقُ فِي الظَّلْمَاءِ مِنْ إِضَمِ"],["فَمَا لِعَيْنَيْكَ إِنْ قُلْتَ اكْفُفَا هَمَتَا","وَمَا لِقَلْبِكَ إِنْ قُلْتَ اسْتَفِقْ يَهِمِ"],["أَيَحْسَبُ الصَّبُّ أَنَّ الْحُبَّ مُنْكَتِمٌ","مَا بَيْنَ مُنْسَجِمٍ مِنْهُ وَمُضْطَرِمِ"],["لَوْلَا الْهَوَى لَمْ تُرِقْ دَمْعًا عَلَى طَلَلٍ","وَلَا أَرِقْتَ لِذِكْرِ الْبَانِ وَالْعَلَمِ"],["مَنْ لِي بِرَدِّ جِمَاحٍ مِنْ غَوَايَتِهَا","كَمَا يُرَدُّ جِمَاحُ الْخَيْلِ بِاللُّجُمِ"],["فَلَا تَرُمْ بِالْمَعَاصِي كَسْرَ شَهْوَتِهَا","إِنَّ الطَّعَامَ يُقَوِّي شَهْوَةَ النَّهِمِ"],["وَالنَّفْسُ كَالطِّفْلِ إِنْ تُهْمِلْهُ شَبَّ عَلَى","حُبِّ الرَّضَاعِ وَإِنْ تَفْطِمْهُ يَنْفَطِمِ"],["فَاصْرِفْ هَوَاهَا وَحَاذِرْ أَنْ تُوَلِّيَهُ","إِنَّ الْهَوَى مَا تَوَلَّى يُصْمِ أَوْ يَصِمِ"],["وَخَالِفِ النَّفْسَ وَالشَّيْطَانَ وَاعْصِهِمَا","وَإِنْ هُمَا مَحَضَاكَ النُّصْحَ فَاتَّهِمِ"],["وَلَا تُطِعْ مِنْهُمَا خَصْمًا وَلَا حَكَمًا","فَأَنْتَ تَعْرِفُ كَيْدَ الْخَصْمِ وَالْحَكَمِ"],["مُحَمَّدٌ سَيِّدُ الْكَوْنَيْنِ وَالثَّقَلَيْ","نِ وَالْفَرِيقَيْنِ مِنْ عُرْبٍ وَمِنْ عَجَمِ"],["نَبِيُّنَا الْآمِرُ النَّاهِي فَلَا أَحَدٌ","أَبَرَّ فِي قَوْلِ لَا مِنْهُ وَلَا نَعَمِ"],["هُوَ الْحَبِيبُ الَّذِي تُرْجَى شَفَاعَتُهُ","لِكُلِّ هَوْلٍ مِنَ الْأَهْوَالِ مُقْتَحَمِ"],["دَعَا إِلَى اللَّهِ فَالْمُسْتَمْسِكُونَ بِهِ","مُسْتَمْسِكُونَ بِحَبْلٍ غَيْرِ مُنْفَصِمِ"],["فَاقَ النَّبِيِّينَ فِي خَلْقٍ وَفِي خُلُقٍ","وَلَمْ يُدَانُوهُ فِي عِلْمٍ وَلَا كَرَمِ"],["فَهْوَ الَّذِي تَمَّ مَعْنَاهُ وَصُورَتُهُ","ثُمَّ اصْطَفَاهُ حَبِيبًا بَارِئُ النَّسَمِ"],["مُنَزَّهٌ عَنْ شَرِيكٍ فِي مَحَاسِنِهِ","فَجَوْهَرُ الْحُسْنِ فِيهِ غَيْرُ مُنْقَسِمِ"],["دَعْ مَا ادَّعَتْهُ النَّصَارَى فِي نَبِيِّهِمِ","وَاحْكُمْ بِمَا شِئْتَ مَدْحًا فِيهِ وَاحْتَكِمِ"],["فَمَبْلَغُ الْعِلْمِ فِيهِ أَنَّهُ بَشَرٌ","وَأَنَّهُ خَيْرُ خَلْقِ اللَّهِ كُلِّهِمِ"],["أَكْرِمْ بِخَلْقِ نَبِيٍّ زَانَهُ خُلُقٌ","بِالْحُسْنِ مُشْتَمِلٍ بِالْبِشْرِ مُتَّسِمِ"],["كَالزَّهْرِ فِي تَرَفٍ وَالْبَدْرِ فِي شَرَفٍ","وَالْبَحْرِ فِي كَرَمٍ وَالدَّهْرِ فِي هِمَمِ"],["كَأَنَّهُ وَهْوَ فَرْدٌ مِنْ جَلَالَتِهِ","فِي عَسْكَرٍ حِينَ تَلْقَاهُ وَفِي حَشَمِ"],["آيَاتُ حَقٍّ مِنَ الرَّحْمَنِ مُحْدَثَةٌ","قَدِيمَةٌ صِفَةُ الْمَوْصُوفِ بِالْقِدَمِ"],["لَمْ تَقْتَرِنْ بِزَمَانٍ وَهْيَ تُخْبِرُنَا","عَنِ الْمَعَادِ وَعَنْ عَادٍ وَعَنْ إِرَمِ"],["دَامَتْ لَدَيْنَا فَفَاقَتْ كُلَّ مُعْجِزَةٍ","مِنَ النَّبِيِّينَ إِذْ جَاءَتْ وَلَمْ تَدُمِ"],["لَهَا مَعَانٍ كَمَوْجِ الْبَحْرِ فِي مَدَدٍ","وَفَوْقَ جَوْهَرِهِ فِي الْحُسْنِ وَالْقِيَمِ"],["فَمَا تُعَدُّ وَلَا تُحْصَى عَجَائِبُهَا","وَلَا تُسَامُ عَلَى الْإِكْثَارِ بِالسَّأَمِ"],["قَرَّتْ بِهَا عَيْنُ قَارِيهَا فَقُلْتُ لَهُ","لَقَدْ ظَفِرْتَ بِحَبْلِ اللَّهِ فَاعْتَصِمِ"],["لَا تَعْجَبَنْ لِحَسُودٍ رَاحَ يُنْكِرُهَا","تَجَاهُلًا وَهْوَ عَيْنُ الْحَاذِقِ الْفَهِمِ"],["قَدْ تُنْكِرُ الْعَيْنُ ضَوْءَ الشَّمْسِ مِنْ رَمَدٍ","وَيُنْكِرُ الْفَمُ طَعْمَ الْمَاءِ مِنْ سَقَمِ"],["سَرَيْتَ مِنْ حَرَمٍ لَيْلًا إِلَى حَرَمِ","كَمَا سَرَى الْبَدْرُ فِي دَاجٍ مِنَ الظُّلَمِ"],["وَبِتَّ تَرْقَى إِلَى أَنْ نِلْتَ مَنْزِلَةً","مِنْ قَابِ قَوْسَيْنِ لَمْ تُدْرَكْ وَلَمْ تُرَمِ"],["وَقَدَّمَتْكَ جَمِيعُ الْأَنْبِيَاءِ بِهَا","وَالرُّسْلِ تَقْدِيمَ مَخْدُومٍ عَلَى خَدَمِ"],["وَأَنْتَ تَخْتَرِقُ السَّبْعَ الطِّبَاقَ بِهِمْ","فِي مَوْكِبٍ كُنْتَ فِيهِ صَاحِبَ الْعَلَمِ"],["فَحُزْتَ كُلَّ فَخَارٍ غَيْرِ مُشْتَرَكٍ","وَجُزْتَ كُلَّ مَقَامٍ غَيْرِ مُزْدَحَمِ"],["بُشْرَى لَنَا مَعْشَرَ الْإِسْلَامِ إِنَّ لَنَا","مِنَ الْعِنَايَةِ رُكْنًا غَيْرَ مُنْهَدِمِ"],["لَمَّا دَعَا اللَّهُ دَاعِينَا لِطَاعَتِهِ","بِأَكْرَمِ الرُّسْلِ كُنَّا أَكْرَمَ الْأُمَمِ"],["كَيْفَ تَرْقَى رُقِيَّكَ الْأَنْبِيَاءُ","يَا سَمَاءً مَا طَاوَلَتْهَا سَمَاءُ"],["لَمْ يُسَاوُوكَ فِي عُلَاكَ وَقَدْ حَا","لَ سَنًا مِنْكَ دُونَهُمْ وَسَنَاءُ"],["إِنَّمَا مَثَّلُوا صِفَاتِكَ لِلنَّا","سِ كَمَا مَثَّلَ النُّجُومَ الْمَاءُ"],["لَمْ تَزَلْ فِي ضَمَائِرِ الْكَوْنِ تُخْتَا","رُ لَكَ الْأُمَّهَاتُ وَالْآبَاءُ"],["مَا مَضَتْ فَتْرَةٌ مِنَ الرُّسْلِ إِلَّا","بَشَّرَتْ قَوْمَهَا بِكَ الْأَنْبِيَاءُ"],["تَتَبَاهَى بِكَ الْعُصُورُ وَتَسْمُو","بِكَ عَلْيَاءٌ بَعْدَهَا عَلْيَاءُ"],["وَبَدَا لِلْوُجُودِ مِنْكَ كَرِيمٌ","مِنْ كَرِيمٍ آبَاؤُهُ كُرَمَاءُ"],["سَيِّدٌ ضِحْكُهُ التَّبَسُّمُ وَالْمَشْ","يُ الْهُوَيْنَا وَنَوْمُهُ الْإِغْفَاءُ"],["مَا سِوَى خُلْقِهِ النَّسِيمُ وَلَا غَيْ","رَ مُحَيَّاهُ الرَّوْضَةُ الْغَنَّاءُ"],["رَحْمَةٌ كُلُّهُ وَحَزْمٌ وَعَزْمٌ","وَوَقَارٌ وَعِصْمَةٌ وَحَيَاءُ"],["لَا تَحُلُّ الْبَأْسَاءُ مِنْهُ عُرَى الصَّبْ","رِ وَلَا تَسْتَخِفُّهُ السَّرَّاءُ"],["كَرُمَتْ نَفْسُهُ فَمَا يَخْطُرُ السُّو","ءُ عَلَى قَلْبِهِ وَلَا الْفَحْشَاءُ"],["عَظُمَتْ نِعْمَةُ الْإِلَهِ عَلَيْهِ","فَاسْتَقَلَّتْ لِذِكْرِهِ الْعُظَمَاءُ"],["جَهِلَتْ قَوْمُهُ عَلَيْهِ فَأَغْضَى","وَأَخُو الْحِلْمِ دَأْبُهُ الْإِغْضَاءُ"],["وَسِعَ الْعَالَمِينَ عِلْمًا وَحِلْمًا","فَهْوَ بَحْرٌ لَمْ تُعْيِهِ الْأَعْبَاءُ"],["يَا رَائِدَ الْبَرْقِ يَمِّمْ دَارَةَ الْعَلَمِ","وَاحْدُ الْغَمَامَ إِلَى حَيٍّ بِذِي سَلَمِ"],["وَإِنْ مَرَرْتَ عَلَى الرَّوْحَاءِ فَامْرِ لَهَا","أَخْلَافَ سَارِيَةٍ هَتَّانَةِ الدِّيَمِ"],["أَدْعُو إِلَى الدَّارِ بِالسُّقْيَا وَبِي ظَمَأٌ","أَحَقُّ بِالرِّيِّ لَكِنِّي أَخُو كَرَمِ"],["مُحَمَّدٌ خَاتَمُ الرُّسْلِ الَّذِي خَضَعَتْ","لَهُ الْبَرِيَّةُ مِنْ عُرْبٍ وَمِنْ عَجَمِ"],["سَمِيرُ وَحْيٍ وَمَجْنَى حِكْمَةٍ وَنَدَى","سَمَاحَةٍ وَقِرَى عَافٍ وَرِيُّ ظَمِ"],["قَدْ أَبْلَغَ الْوَحْيُ عَنْهُ قَبْلَ بِعْثَتِهِ","مَسَامِعَ الرُّسْلِ قَوْلًا غَيْرَ مُنْكَتِمِ"],["فَذَاكَ دَعْوَةُ إِبْرَاهِيمَ خَالِقَهُ","وَسِرُّ مَا قَالَهُ عِيسَى مِنَ الْقِدَمِ"],["أَكْرِمْ بِهِ وَبِآبَاءٍ مُحَجَّلَةٍ","جَاءَتْ بِهِ غُرَّةً فِي الْأَعْصُرِ الدُّهُمِ"],["تَابَعْتُ كَعْبًا وَحَسَّانًا وَلِي بِهِمَا","فِي الْقَوْلِ أُسْوَةُ بَرٍّ غَيْرِ مُتَّهَمِ"],["وَالشِّعْرُ مَعْرِضُ أَلْبَابٍ يَرُوجُ بِهِ","مَا نَمَّقَتْهُ يَدُ الْآدَابِ وَالْحِكَمِ"],["فَلَا يَلُمْنِي عَلَى التَّشْبِيبِ ذُو عَنَتٍ","فَبُلْبُلُ الرَّوْضِ مَطْبُوعٌ عَلَى النَّغَمِ"],["وَلَيْسَ لِي رَوْضَةٌ أَلْهُو بِزَهْرَتِهَا","فِي مَعْرِضِ الْقَوْلِ إِلَّا رَوْضَةُ الْحَرَمِ"],["وَصَلِّ رَبِّ عَلَى الْمُخْتَارِ مَا طَلَعَتْ","شَمْسُ النَّهَارِ وَلَاحَتْ أَنْجُمُ الظُّلَمِ"],["وَالْآلِ وَالصَّحْبِ وَالْأَنْصَارِ مَنْ تَبِعُوا","هُدَاهُ وَاعْتَرَفُوا بِالْعَهْدِ وَالذِّمَمِ"],["وَامْنُنْ عَلَى عَبْدِكَ الْعَانِي بِمَغْفِرَةٍ","تَمْحُو خَطَايَاهُ فِي بَدْءٍ وَمُخْتَتَمِ"],["رِيمٌ عَلَى الْقَاعِ بَيْنَ الْبَانِ وَالْعَلَمِ","أَحَلَّ سَفْكَ دَمِي فِي الْأَشْهُرِ الْحُرُمِ"],["رَمَى الْقَضَاءُ بِعَيْنَيْ جُؤْذَرٍ أَسَدًا","يَا سَاكِنَ الْقَاعِ أَدْرِكْ سَاكِنَ الْأَجَمِ"],["لَمَّا رَنَا حَدَّثَتْنِي النَّفْسُ قَائِلَةً","يَا وَيْحَ جَنْبِكَ بِالسَّهْمِ الْمُصِيبِ رُمِي"],["جَحَدْتُهَا وَكَتَمْتُ السَّهْمَ فِي كَبِدِي","جُرْحُ الْأَحِبَّةِ عِنْدِي غَيْرُ ذِي أَلَمِ"],["يَا نَفْسُ دُنْيَاكِ تُخْفِي كُلَّ مُبْكِيَةٍ","وَإِنْ بَدَا لَكِ مِنْهَا حُسْنُ مُبْتَسَمِ"],["صَلَاحُ أَمْرِكَ لِلْأَخْلَاقِ مَرْجِعُهُ","فَقَوِّمِ النَّفْسَ بِالْأَخْلَاقِ تَسْتَقِمِ"],["وَالنَّفْسُ مِنْ خَيْرِهَا فِي خَيْرِ عَافِيَةٍ","وَالنَّفْسُ مِنْ شَرِّهَا فِي مَرْتَعٍ وَخِمِ"],["تَطْغَى إِذَا مُكِّنَتْ مِنْ لَذَّةٍ وَهَوًى","طَغْيَ الْجِيَادِ إِذَا عَضَّتْ عَلَى الشُّكُمِ"],["إِنْ جَلَّ ذَنْبِي عَنِ الْغُفْرَانِ لِي أَمَلٌ","فِي اللَّهِ يَجْعَلُنِي فِي خَيْرِ مُعْتَصَمِ"],["مُحَمَّدٌ صَفْوَةُ الْبَارِي وَرَحْمَتُهُ","وَبُغْيَةُ اللَّهِ مِنْ خَلْقٍ وَمِنْ نَسَمِ"],["وَنُودِيَ اقْرَأْ تَعَالَى اللَّهُ قَائِلُهَا","لَمْ تَتَّصِلْ قَبْلَ مَنْ قِيلَتْ لَهُ بِفَمِ"],["هُنَاكَ أَذَّنَ لِلرَّحْمَنِ فَامْتَلَأَتْ","أَسْمَاعُ مَكَّةَ مِنْ قُدْسِيَّةِ النَّغَمِ"],["يَا جَاهِلِينَ عَلَى الْهَادِي وَدَعْوَتِهِ","هَلْ تَجْهَلُونَ مَكَانَ الصَّادِقِ الْعَلَمِ"],["لَقَّبْتُمُوهُ أَمِينَ الْقَوْمِ فِي صِغَرٍ","وَمَا الْأَمِينُ عَلَى قَوْلٍ بِمُتَّهَمِ"],["فَاقَ الْبُدُورَ وَفَاقَ الْأَنْبِيَاءَ فَكَمْ","بِالْخُلْقِ وَالْخَلْقِ مِنْ حُسْنٍ وَمِنْ عِظَمِ"],["جَاءَ النَّبِيُّونَ بِالْآيَاتِ فَانْصَرَمَتْ","وَجِئْتَنَا بِحَكِيمٍ غَيْرِ مُنْصَرِمِ"],["آيَاتُهُ كُلَّمَا طَالَ الْمَدَى جُدُدٌ","يَزِينُهُنَّ جَلَالُ الْعِتْقِ وَالْقِدَمِ"],["يَكَادُ فِي لَفْظَةٍ مِنْهُ مُشَرَّفَةٍ","يُوصِيكَ بِالْحَقِّ وَالتَّقْوَى وَبِالرَّحِمِ"],["يَا أَفْصَحَ النَّاطِقِينَ الضَّادَ قَاطِبَةً","حَدِيثُكَ الشَّهْدُ عِنْدَ الذَّائِقِ الْفَهِمِ"],["حَلَّيْتَ مِنْ عَطَلٍ جِيدَ الْبَيَانِ بِهِ","فِي كُلِّ مُنْتَثِرٍ فِي حُسْنِ مُنْتَظِمِ"],["بِكُلِّ قَوْلٍ كَرِيمٍ أَنْتَ قَائِلُهُ","تُحْيِي الْقُلُوبَ وَتُحْيِي مَيِّتَ الْهِمَمِ"],["أَتَيْتَ وَالنَّاسُ فَوْضَى لَا تَمُرُّ بِهِمْ","إِلَّا عَلَى صَنَمٍ قَدْ هَامَ فِي صَنَمِ"],["وَالْأَرْضُ مَمْلُوءَةٌ جَوْرًا مُسَخَّرَةٌ","لِكُلِّ طَاغِيَةٍ فِي الْخَلْقِ مُحْتَكِمِ"],["أَسْرَى بِكَ اللَّهُ لَيْلًا إِذْ مَلَائِكُهُ","وَالرُّسْلُ فِي الْمَسْجِدِ الْأَقْصَى عَلَى قَدَمِ"],["لَمَّا خَطَرْتَ بِهِ التَّفُّوا بِسَيِّدِهِمْ","كَالشُّهْبِ بِالْبَدْرِ أَوْ كَالْجُنْدِ بِالْعَلَمِ"],["صَلَّى وَرَاءَكَ مِنْهُمْ كُلُّ ذِي خَطَرٍ","وَمَنْ يَفُزْ بِحَبِيبِ اللَّهِ يَأْتَمِمِ"],["ذُكِرْتَ بِالْيُتْمِ فِي الْقُرْآنِ تَكْرِمَةً","وَقِيمَةُ اللُّؤْلُؤِ الْمَكْنُونِ فِي الْيُتُمِ"],["أَخُوكَ عِيسَى دَعَا مَيْتًا فَقَامَ لَهُ","وَأَنْتَ أَحْيَيْتَ أَجْيَالًا مِنَ الرِّمَمِ"],["يَا رَبِّ هَبَّتْ شُعُوبٌ مِنْ مَنِيَّتِهَا","وَاسْتَيْقَظَتْ أُمَمٌ مِنْ رَقْدَةِ الْعَدَمِ"],["سَعْدٌ وَنَحْسٌ وَمُلْكٌ أَنْتَ مَالِكُهُ","تُدِيلُ مِنْ نِعَمٍ فِيهِ وَمِنْ نِقَمِ"],["رَأَى قَضَاؤُكَ فِينَا رَأْيَ حِكْمَتِهِ","أَكْرِمْ بِوَجْهِكَ مِنْ قَاضٍ وَمُنْتَقِمِ"],["يَا رَبِّ أَحْسَنْتَ بَدْءَ الْمُسْلِمِينَ بِهِ","فَتَمِّمِ الْفَضْلَ وَامْنَحْ حُسْنَ مُخْتَتَمِ"],["وُلِدَ الْهُدَى فَالْكَائِنَاتُ ضِيَاءُ","وَفَمُ الزَّمَانِ تَبَسُّمٌ وَثَنَاءُ"],["الرُّوحُ وَالْمَلَأُ الْمَلَائِكُ حَوْلَهُ","لِلدِّينِ وَالدُّنْيَا بِهِ بُشَرَاءُ"],["وَالْعَرْشُ يَزْهُو وَالْحَظِيرَةُ تَزْدَهِي","وَالْمُنْتَهَى وَالسِّدْرَةُ الْعَصْمَاءُ"],["وَالْوَحْيُ يَقْطُرُ سَلْسَلًا مِنْ سَلْسَلٍ","وَاللَّوْحُ وَالْقَلَمُ الْبَدِيعُ رُوَاءُ"],["نُظِمَتْ أَسَامِي الرُّسْلِ فَهْيَ صَحِيفَةٌ","فِي اللَّوْحِ وَاسْمُ مُحَمَّدٍ طُغَرَاءُ"],["يَا خَيْرَ مَنْ جَاءَ الْوُجُودَ تَحِيَّةً","مِنْ مُرْسَلِينَ إِلَى الْهُدَى بِكَ جَاءُوا"],["بِكَ بَشَّرَ اللَّهُ السَّمَاءَ فَزُيِّنَتْ","وَتَضَوَّعَتْ مِسْكًا بِكَ الْغَبْرَاءُ"],["وَبَدَا مُحَيَّاكَ الَّذِي قَسَمَاتُهُ","حَقٌّ وَغُرَّتُهُ هُدًى وَحَيَاءُ"],["وَعَلَيْهِ مِنْ نُورِ النُّبُوَّةِ رَوْنَقٌ","وَمِنَ الْخَلِيلِ وَهَدْيِهِ سِيمَاءُ"],["يَوْمٌ يَتِيهُ عَلَى الزَّمَانِ صَبَاحُهُ","وَمَسَاؤُهُ بِمُحَمَّدٍ وَضَّاءُ"],["الْحَقُّ عَالِي الرُّكْنِ فِيهِ مُظَفَّرٌ","فِي الْمُلْكِ لَا يَعْلُو عَلَيْهِ لِوَاءُ"],["نِعْمَ الْيَتِيمُ بَدَتْ مَخَايِلُ فَضْلِهِ","وَالْيُتْمُ رِزْقٌ بَعْضُهُ وَذَكَاءُ"],["بِسِوَى الْأَمَانَةِ فِي الصِّبَا وَالصِّدْقِ لَمْ","يَعْرِفْهُ أَهْلُ الصِّدْقِ وَالْأُمَنَاءُ"],["يَا مَنْ لَهُ الْأَخْلَاقُ مَا تَهْوَى الْعُلَا","مِنْهَا وَمَا يَتَعَشَّقُ الْكُبَرَاءُ"],["لَوْ لَمْ تُقِمْ دِينًا لَقَامَتْ وَحْدَهَا","دِينًا تُضِيءُ بِنُورِهِ الْآنَاءُ"],["زَانَتْكَ فِي الْخُلُقِ الْعَظِيمِ شَمَائِلٌ","يُغْرَى بِهِنَّ وَيُولَعُ الْكُرَمَاءُ"],["فَإِذَا سَخَوْتَ بَلَغْتَ بِالْجُودِ الْمَدَى","وَفَعَلْتَ مَا لَا تَفْعَلُ الْأَنْوَاءُ"],["وَإِذَا عَفَوْتَ فَقَادِرًا وَمُقَدَّرًا","لَا يَسْتَهِينُ بِعَفْوِكَ الْجُهَلَاءُ"],["وَإِذَا رَحِمْتَ فَأَنْتَ أُمٌّ أَوْ أَبٌ","هَذَانِ فِي الدُّنْيَا هُمَا الرُّحَمَاءُ"],["وَإِذَا غَضِبْتَ فَإِنَّمَا هِيَ غَضْبَةٌ","فِي الْحَقِّ لَا ضِغْنٌ وَلَا بَغْضَاءُ"],["وَإِذَا رَضِيتَ فَذَاكَ فِي مَرْضَاتِهِ","وَرِضَا الْكَثِيرِ تَحَلُّمٌ وَرِيَاءُ"],["وَإِذَا خَطَبْتَ فَلِلْمَنَابِرِ هِزَّةٌ","تَعْرُو النَّدِيَّ وَلِلْقُلُوبِ بُكَاءُ"],["وَإِذَا قَضَيْتَ فَلَا ارْتِيَابَ كَأَنَّمَا","جَاءَ الْخُصُومَ مِنَ السَّمَاءِ قَضَاءُ"],["وَإِذَا صَحِبْتَ رَأَى الْوَفَاءَ مُجَسَّمًا","فِي بُرْدِكَ الْأَصْحَابُ وَالْخُلَطَاءُ"],["وَإِذَا أَخَذْتَ الْعَهْدَ أَوْ أَعْطَيْتَهُ","فَجَمِيعُ عَهْدِكَ ذِمَّةٌ وَوَفَاءُ"],["وَتَمُدُّ حِلْمَكَ لِلسَّفِيهِ مُدَارِيًا","حَتَّى يَضِيقَ بِعِرْضِكَ السُّفَهَاءُ"],["فِي كُلِّ نَفْسٍ مِنْ سُطَاكَ مَهَابَةٌ","وَلِكُلِّ نَفْسٍ فِي نَدَاكَ رَجَاءُ"],["سَلُوا قَلْبِي غَدَاةَ سَلَا وَتَابَا","لَعَلَّ عَلَى الْجَمَالِ لَهُ عِتَابَا"],["وَيُسْأَلُ فِي الْحَوَادِثِ ذُو صَوَابٍ","فَهَلْ تَرَكَ الْجَمَالُ لَهُ صَوَابَا"],["وَكُنْتُ إِذَا سَأَلْتُ الْقَلْبَ يَوْمًا","تَوَلَّى الدَّمْعُ عَنْ قَلْبِي الْجَوَابَا"],["وَسَوَّى اللَّهُ بَيْنَكُمُ الْمَنَايَا","وَوَسَّدَكُمْ مَعَ الرُّسْلِ التُّرَابَا"],["وَأَرْسَلَ عَائِلًا مِنْكُمْ يَتِيمًا","دَنَا مِنْ ذِي الْجَلَالِ فَكَانَ قَابَا"],["نَبِيُّ الْبِرِّ بَيَّنَهُ سَبِيلًا","وَسَنَّ خِلَالَهُ وَهَدَى الشِّعَابَا"],["وَعَلَّمَنَا بِنَاءَ الْمَجْدِ حَتَّى","أَخَذْنَا إِمْرَةَ الْأَرْضِ اغْتِصَابَا"],["وَمَا نَيْلُ الْمَطَالِبِ بِالتَّمَنِّي","وَلَكِنْ تُؤْخَذُ الدُّنْيَا غِلَابَا"],["وَمَا اسْتَعْصَى عَلَى قَوْمٍ مَنَالٌ","إِذَا الْإِقْدَامُ كَانَ لَهُمْ رِكَابَا"],["تَجَلَّى مَوْلِدُ الْهَادِي وَعَمَّتْ","بَشَائِرُهُ الْبَوَادِي وَالْقِصَابَا"],["أَبَا الزَّهْرَاءِ قَدْ جَاوَزْتُ قَدْرِي","بِمَدْحِكَ بَيْدَ أَنَّ لِيَ انْتِسَابَا"],["فَمَا عَرَفَ الْبَلَاغَةَ ذُو بَيَانٍ","إِذَا لَمْ يَتَّخِذْكَ لَهُ كِتَابَا"],["مَدَحْتُ الْمَالِكِينَ فَزِدْتُ قَدْرًا","فَحِينَ مَدَحْتُكَ اقْتَدْتُ السَّحَابَا"],["وَلَوْ حَفِظُوا سَبِيلَكَ كَانَ نُورًا","وَكَانَ مِنَ النُّحُوسِ لَهُمْ حِجَابَا"],["بَنَيْتَ لَهُمْ مِنَ الْأَخْلَاقِ رُكْنًا","فَخَانُوا الرُّكْنَ فَانْهَدَمَ اضْطِرَابَا"]],"secs":{"1":"أبو طالب: وأبيض يستسقى الغمام بوجهه (من اللامية)","16":"حسان بن ثابت: أغر عليه للنبوة خاتم","22":"حسان بن ثابت: وأحسن منك لم تر قط عيني","24":"حسان بن ثابت: هجوت محمدًا فأجبت عنه (من الهمزية)","34":"حسان بن ثابت: بطيبة رسم للرسول ومعهد","47":"عبد الله بن رواحة: وفينا رسول الله يتلو كتابه","50":"العباس بن عبد المطلب: من قبلها طبت في الظلال","57":"كعب بن زهير: بانت سعاد (أبيات المديح)","67":"الأعشى: ألم تغتمض عيناك (أبيات المديح)","74":"البوصيري: البردة — المطلع","79":"البوصيري: البردة — في التحذير من هوى النفس","85":"البوصيري: البردة — في مدحه ﷺ","97":"البوصيري: البردة — في القرآن","105":"البوصيري: البردة — في الإسراء والمعراج","112":"البوصيري: الهمزية — المطلع","119":"البوصيري: الهمزية — في شمائله ﷺ","127":"البارودي: كشف الغمة — المطلع والمديح","135":"البارودي: كشف الغمة — الخاتمة","142":"شوقي: نهج البردة — المطلع","146":"شوقي: نهج البردة — في النفس والأخلاق","151":"شوقي: نهج البردة — في مدحه ﷺ ورسالته","170":"شوقي: نهج البردة — الدعاء","174":"شوقي: الهمزية النبوية — المولد","187":"شوقي: الهمزية النبوية — الأخلاق والشمائل","201":"شوقي: سلوا قلبي — المطلع","204":"شوقي: سلوا قلبي — نبي البر","211":"شوقي: سلوا قلبي — أبا الزهراء"}}],"sharh":false};
